import{_ as o,o as d,c as e,a2 as i}from"./chunks/framework.BZAK_utg.js";const C=JSON.parse('{"title":"macOS键盘快捷键配置","description":"","frontmatter":{"title":"macOS键盘快捷键配置","date":"2026-05-30","categories":["安装配置","应用软件"],"tags":["macOS"],"prevTitle":"跨平台UI框架汇总","prevLink":"../编程语言/跨平台UI框架汇总.html","nextTitle":"Distrobox快速上手","nextLink":"./Distrobox快速上手.html"},"headers":[],"relativePath":"posts/安装配置/macOS键盘快捷键配置.md","filePath":"posts/安装配置/macOS键盘快捷键配置.md"}'),n={name:"posts/安装配置/macOS键盘快捷键配置.md"};function a(r,t,l,s,h,m){return d(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="macos键盘快捷键配置" tabindex="-1">macOS键盘快捷键配置 <a class="header-anchor" href="#macos键盘快捷键配置" aria-label="Permalink to &quot;macOS键盘快捷键配置&quot;">​</a></h1><p>为了实现Windows、Linux、macOS三个平台一致的键盘快捷键体验，核心策略是统一使用Windows与Linux风格的快捷键，调整macOS下的Control键和Command键的映射关系，并微调macOS部分快捷键配置。</p><p>Control键映射为Command键，坏处很明显，需要放弃所有的原生Control组合功能，包括Control+C停止命令等常用终端命令。对于iTerm等终端工具，可以单独设置快捷键以实现Control+C的效果，但对于Jetbrains和VSCode等终端界面，无法很好的支持需要Control组合的快捷键。</p><p>Control键映射为Command键的同时，也将Command键也映射为Control键（双向映射），可以通过Command+C实现原来Control+C的功能，但又会打乱macOS原本的一些快捷键习惯，如：Command+Tab切换窗口、Command+Space打开聚焦搜索、Command+Q关闭应用等都需要切换为Control组合快捷键。</p><p>没有一套完美的跨平台快捷键统一方案，下文提供一种将Control键映射为Command键的配套修改思路，以供参考。</p><h3 id="一、macos全局快捷键" tabindex="-1">一、macOS全局快捷键 <a class="header-anchor" href="#一、macos全局快捷键" aria-label="Permalink to &quot;一、macOS全局快捷键&quot;">​</a></h3><p>点击【设置】-【键盘】-【键盘快捷键】，进入系统快捷键设置界面。</p><p>将【修饰符】中的【Control键】修改为【Commond键】，以适配Windows/Linux的使用习惯。</p><table tabindex="0"><thead><tr><th>动作</th><th>原快捷键</th><th>新快捷键</th><th>备注</th></tr></thead><tbody><tr><td>服务/搜索/聚焦</td><td>Shift+Command+F</td><td>-</td><td>避免与Jetbrains快捷键冲突</td></tr><tr><td>聚焦/显示APP</td><td>-</td><td>Option+A</td><td>-</td></tr></tbody></table><h3 id="二、jetbrains快捷键" tabindex="-1">二、Jetbrains快捷键 <a class="header-anchor" href="#二、jetbrains快捷键" aria-label="Permalink to &quot;二、Jetbrains快捷键&quot;">​</a></h3><p>点击【Settings】-【Keymap】，进入IDEA/PyCharm快捷键设置界面。</p><p>切换预定义的键位映射为：【Intellij IDEA Classic】。</p><table tabindex="0"><thead><tr><th>动作</th><th>原快捷键</th><th>新快捷键</th><th>备注</th></tr></thead><tbody><tr><td>Move Caret to Previous Word</td><td>Option+←</td><td>Command+←</td><td>-</td></tr><tr><td>Move Caret to Next Word</td><td>Option+→</td><td>Command+→</td><td>-</td></tr><tr><td>Move Caret to Previous Word with Selection</td><td>Option+Shift+←</td><td>Command+Shift+←</td><td>-</td></tr><tr><td>Move Caret to Next Word with Selection</td><td>Option+Shift+→</td><td>Command+Shift+→</td><td>-</td></tr><tr><td>Next Method</td><td>Control+↓</td><td>Option+↓</td><td>-</td></tr><tr><td>Previous Method</td><td>Control+↑</td><td>Option+↑</td><td>-</td></tr><tr><td>Select Next Tab</td><td>Control+→</td><td>Option+→</td><td></td></tr><tr><td>Select Previous Tab</td><td>Control+←</td><td>Option+←</td><td></td></tr><tr><td>Find in Files</td><td>Control+Shift+F</td><td>Command+Shift+F</td><td>-</td></tr><tr><td>Replace in Files</td><td>Control+Shift+R</td><td>Command+Shift+R</td><td>-</td></tr></tbody></table><p>其它不一致的快捷键：</p><ul><li>top：Show Project window、<strong>Settings</strong>、Generate、<strong>Run Anything</strong>、Attach to Process</li><li>Build projects：New in This Directory</li><li>Basic editing：Join Lines、Scratch File</li><li>Multiple carets and selection ranges：...</li><li>Coding assistance：Basic Completion、Type-Matching Completion、Second Basic Completion、Complete Code with AI Assistant、Generate Code with AI Assistant、Quick Documentation、Generate</li><li>Context navigation：<strong>Switcher</strong>、Toggle Anonymous Bookmark、Toggle Bookmark with Digit、Go to Bookmark with Digit、Show Mnemonic Bookmarks、Show Bookmarks window、Show Structure window、Show Find window Code analysis：Show Problems window</li><li>Run and debug：<strong>Run Anything</strong>、Attach to Process、Show Run window、Show Debug window、Show Services window</li><li>Refactorings：Safe Delete</li><li>Global VCS actions：VCS Operations Popup、Next Change、Previous Change、Show Version Control window、Show Commit window</li><li>Diff Viewer：Accept Left Side、Accept Right Side、Select Opposite Diff Pane</li><li>Tool windows：含有Option的Show xxx window</li></ul><h3 id="三、iterm快捷键" tabindex="-1">三、iTerm快捷键 <a class="header-anchor" href="#三、iterm快捷键" aria-label="Permalink to &quot;三、iTerm快捷键&quot;">​</a></h3><p>点击【Settings】-【Keys】-【Key Bindings】，进入iTerm快捷键设置界面。</p><table tabindex="0"><thead><tr><th>动作</th><th>原快捷键</th><th>新快捷键</th><th>备注</th></tr></thead><tbody><tr><td>Send Hex Codes: 0x03</td><td>-</td><td>Command+C</td><td>中断命令</td></tr><tr><td>Copy Selection or Send</td><td>-</td><td>Command+Shift+C</td><td>复制</td></tr><tr><td>Paste or Send</td><td>-</td><td>Command+Shift+V</td><td>粘贴</td></tr></tbody></table>',18)])])}const S=o(n,[["render",a]]);export{C as __pageData,S as default};
